    bronze_gardenfrostclothclip = { name = "Bronast scipalke za zadrzevalce mraza", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast scipalke za zadrzevalce mraza za vrtnarje." },
    silver_gardenfrostclothclip = { name = "Srebrn scipalke za zadrzevalce mraza", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn scipalke za zadrzevalce mraza za vrtnarje." },
