}
GardenFrostClothClipMaker.ironStock=14; GardenFrostClothClipMaker.bronzeStock=12; GardenFrostClothClipMaker.woodStock=12; GardenFrostClothClipMaker.leatherStock=8; GardenFrostClothClipMaker.silverStock=8; GardenFrostClothClipMaker.goldStock=6; GardenFrostClothClipMaker.jewelStock=4; GardenFrostClothClipMaker.pearlStock=4
GardenFrostClothClipMaker.productStock = {}; GardenFrostClothClipMaker.buildings = {}; GardenFrostClothClipMaker.maker = nil; GardenFrostClothClipMaker.activeMaking = {}; GardenFrostClothClipMaker.totalProducts = 0; GardenFrostClothClipMaker.dayTimer = 0
function GardenFrostClothClipMaker.init() GardenFrostClothClipMaker.ironStock=14; GardenFrostClothClipMaker.bronzeStock=12; GardenFrostClothClipMaker.woodStock=12; GardenFrostClothClipMaker.leatherStock=8; GardenFrostClothClipMaker.silverStock=8; GardenFrostClothClipMaker.goldStock=6; GardenFrostClothClipMaker.jewelStock=4; GardenFrostClothClipMaker.pearlStock=4; GardenFrostClothClipMaker.productStock={}; GardenFrostClothClipMaker.buildings={}; GardenFrostClothClipMaker.maker=nil; GardenFrostClothClipMaker.activeMaking={}; GardenFrostClothClipMaker.totalProducts=0; GardenFrostClothClipMaker.dayTimer=0; print("[GardenFrostClothClipMaker] Royal Garden Frost Cloth Clip Maker System initialized (6 products, 4 buildings)") end
function GardenFrostClothClipMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenFrostClothClipMaker.maker={name=n or ("Ščipalkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ščipalkar najet: %s (spretnost: %d)",GardenFrostClothClipMaker.maker.name,s),"success") end; return true end
function GardenFrostClothClipMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenFrostClothClipMaker.build(id) local ok,e=GardenFrostClothClipMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenFrostClothClipMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenFrostClothClipMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenFrostClothClipMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenFrostClothClipMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenFrostClothClipMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenFrostClothClipMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenFrostClothClipMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenFrostClothClipMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenFrostClothClipMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenFrostClothClipMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenFrostClothClipMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenFrostClothClipMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenFrostClothClipMaker.buildings==0 then return false,"Potrebna scipalna delavnica" end; if not GardenFrostClothClipMaker.maker then return false,"Potreben scipalkar" end; return true end
function GardenFrostClothClipMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenFrostClothClipMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenFrostClothClipMaker.ironStock=GardenFrostClothClipMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenFrostClothClipMaker.bronzeStock=GardenFrostClothClipMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenFrostClothClipMaker.woodStock=GardenFrostClothClipMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenFrostClothClipMaker.leatherStock=GardenFrostClothClipMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenFrostClothClipMaker.silverStock=GardenFrostClothClipMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenFrostClothClipMaker.goldStock=GardenFrostClothClipMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenFrostClothClipMaker.jewelStock=GardenFrostClothClipMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenFrostClothClipMaker.pearlStock=GardenFrostClothClipMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenFrostClothClipMaker.maker then t=math.max(1,t-math.floor(GardenFrostClothClipMaker.maker.skill/13)) end; table.insert(GardenFrostClothClipMaker.activeMaking,{id="gardenfrostclothclip_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenFrostClothClipMaker.completeMaking(m) local q=1.0+(GardenFrostClothClipMaker.getQualityBonus()/100); if GardenFrostClothClipMaker.maker then q=q+(GardenFrostClothClipMaker.maker.skill/140) end; q=math.min(2.5,q); GardenFrostClothClipMaker.productStock[m.productType]=(GardenFrostClothClipMaker.productStock[m.productType] or 0)+m.quantity; GardenFrostClothClipMaker.totalProducts=GardenFrostClothClipMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenFrostClothClipMaker.maker then GardenFrostClothClipMaker.maker.itemsMade=GardenFrostClothClipMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenFrostClothClipMaker.maker.skill=math.min(100,GardenFrostClothClipMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ščipalka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardenfrostclothclip.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenFrostClothClipMaker.update(dt) if not _G.state then return end; GardenFrostClothClipMaker.dayTimer=GardenFrostClothClipMaker.dayTimer+dt; if GardenFrostClothClipMaker.dayTimer>=30 then GardenFrostClothClipMaker.dayTimer=0; for i=#GardenFrostClothClipMaker.activeMaking,1,-1 do local m=GardenFrostClothClipMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenFrostClothClipMaker.completeMaking(m); table.remove(GardenFrostClothClipMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenFrostClothClipMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenFrostClothClipMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GardenFrostClothClipMaker.getStats() return {ironStock=GardenFrostClothClipMaker.ironStock,bronzeStock=GardenFrostClothClipMaker.bronzeStock,woodStock=GardenFrostClothClipMaker.woodStock,leatherStock=GardenFrostClothClipMaker.leatherStock,silverStock=GardenFrostClothClipMaker.silverStock,goldStock=GardenFrostClothClipMaker.goldStock,jewelStock=GardenFrostClothClipMaker.jewelStock,pearlStock=GardenFrostClothClipMaker.pearlStock,productStock=GardenFrostClothClipMaker.productStock,numBuildings=#GardenFrostClothClipMaker.buildings,hasMaker=GardenFrostClothClipMaker.maker~=nil,makerName=GardenFrostClothClipMaker.maker and GardenFrostClothClipMaker.maker.name or "—",makerSkill=GardenFrostClothClipMaker.maker and GardenFrostClothClipMaker.maker.skill or 0,activeMaking=#GardenFrostClothClipMaker.activeMaking,totalProducts=GardenFrostClothClipMaker.totalProducts} end
return GardenFrostClothClipMaker
